/**
  * @brief at32f403axx standard peripheral library version number
  */
#define __AT32F403A_LIBRARY_VERSION_MAJOR    (0x02) /*!< [31:24] major version */
#define __AT32F403A_LIBRARY_VERSION_MIDDLE   (0x01) /*!< [23:16] middle version */
#define __AT32F403A_LIBRARY_VERSION_MINOR    (0x03) /*!< [15:8]  minor version */
#define __AT32F403A_LIBRARY_VERSION_RC       (0x00) /*!< [7:0]  release candidate */
#define __AT32F403A_LIBRARY_VERSION          ((__AT32F403A_LIBRARY_VERSION_MAJOR  << 24)\
                                             |(__AT32F403A_LIBRARY_VERSION_MIDDLE << 16)\
                                             |(__AT32F403A_LIBRARY_VERSION_MINOR  << 8 )\
                                             |(__AT32F403A_LIBRARY_VERSION_RC))

