#define TMR10_IRQHandler                    TMR1_OVF_TMR10_IRQHandler
#define TMR1_OVF_TMR16_IRQHandler           TMR1_OVF_TMR10_IRQHandler
#define TMR1_OVF_IRQHandler                 TMR1_OVF_TMR10_IRQHandler
#define TMR6_DAC_IRQHandler                 TMR6_GLOBAL_IRQHandler
#define TMR12_IRQHandler                    TMR8_BRK_TMR12_IRQHandler
#define TMR8_BRK_IRQHandler                 TMR8_BRK_TMR12_IRQHandler
#define TMR8_TRG_HALL_IRQHandler            TMR8_TRG_HALL_TMR14_IRQHandler
#define TMR14_IRQHandler                    TMR8_TRG_HALL_TMR14_IRQHandler
#define TMR8_OVF_IRQHandler                 TMR8_OVF_TMR13_IRQHandler
#define TMR13_IRQHandler                    TMR8_OVF_TMR13_IRQHandler
#define CEC_IRQHandler                      USBFSWakeUp_IRQHandler
